from fastapi import APIRouter
from fastapi.responses import PlainTextResponse

router = APIRouter()

@router.get("/report/shift", response_class=PlainTextResponse)
def download_shift_report():
    """Returns a downloadable shift report."""
    # This will later be generated by Claude (claude_helper.py)
    report_content = (
        "AI QUALITY PLATFORM - SHIFT SUMMARY REPORT\n"
        "==========================================\n"
        "Shift: Night\n"
        "Total Inspections: 2\n"
        "Fails: 2 (Defect Rate: 100%)\n"
        "\n"
        "CLAUDE ANALYSIS:\n"
        "The night shift experienced a critical failure rate primarily due to 'scratch' defects. "
        "Maintenance is advised to check the conveyor alignment for BATCH-999."
    )
    return report_content
